with open('main.py', 'w', encoding='utf-8') as f: 
    f.write('''from src.models.dixon_coles import calcular_probabilidades_partido\nfrom src.progol.optimizer import evaluar_valor_partido\nfrom src.bookmakers.kelly import remover_vig, evaluar_apuesta_kelly\n\ndef analizar_partido_completo(local_name, visitante_name, local_xg, visitante_xg, c_l, c_e, c_v, pct_pub_l, pct_pub_e, pct_pub_v):\n    print("==================================================")\n    print(f" ANALISIS PREDICTIVO: {local_name} vs {visitante_name}")\n    print("==================================================")\n    \n    probs = calcular_probabilidades_partido(local_xg, visitante_xg)\n    print("\\n[1] PROBABILIDADES MODELO IA (DIXON-COLES)")\n    print(f"  Local (1):     {probs[\'prob_local\']*100:.2f}%")\n    print(f"  Empate (X):    {probs[\'prob_empate\']*100:.2f}%")\n    print(f"  Visitante (2): {probs[\'prob_visitante\']*100:.2f}%")\n    \n    ev_p_l = evaluar_valor_partido(probs["prob_local"], pct_pub_l)\n    ev_p_e = evaluar_valor_partido(probs["prob_empate"], pct_pub_e)\n    ev_p_v = evaluar_valor_partido(probs["prob_visitante"], pct_pub_v)\n    print("\\n[2] EVALUACION DE POZO PROGOL (+EV)")\n    print(f"  Indice Valor Local:     {ev_p_l}")\n    print(f"  Indice Valor Empate:    {ev_p_e} {\'<-- SUGERENCIA DE POZO\' if ev_p_e > 1.1 else \'\'}")\n    print(f"  Indice Valor Visitante: {ev_p_v} {\'<-- SUGERENCIA DE POZO\' if ev_p_v > 1.1 else \'\'}")\n    \n    vig_info = remover_vig(c_l, c_e, c_v)\n    kelly_l = evaluar_apuesta_kelly(probs["prob_local"], c_l)\n    kelly_e = evaluar_apuesta_kelly(probs["prob_empate"], c_e)\n    kelly_v = evaluar_apuesta_kelly(probs["prob_visitante"], c_v)\n    \n    print("\\n[3] EVALUACION FINANCIERA (CASAS DE APUESTAS)")\n    print(f"  Margen de la Casa (Vig): {vig_info[\'overround_pct\']}%")\n    for opc, res, c_val in [("Local", kelly_l, c_l), ("Empate", kelly_e, c_e), ("Visitante", kelly_v, c_v)]:\n        if res["apostar"]:\n            print(f"  -> OPTION {opc} @ {c_val}: APUESTA RECOMENDADA | +EV: {res[\'ev\']} | Stake: {res[\'stake_pct\']}% del Bankroll")\n        else:\n            print(f"  -> OPTION {opc} @ {c_val}: SIN VALOR ESPERADO (EV <= 0)")\n\nif __name__ == "__main__":\n    analizar_partido_completo(\n        local_name="America", visitante_name="Chivas",\n        local_xg=1.85, visitante_xg=1.10,\n        c_l=2.10, c_e=3.40, c_v=3.60,\n        pct_pub_l=65.0, pct_pub_e=20.0, pct_pub_v=15.0\n    )\n''') 
